/*
 * log.h — Verbose logging for the Epilog runtime.
 *
 * When --verbose or -v is passed, every major step is logged to stderr.
 *
 * JPL rules: no heap, no recursion, bounded format strings.
 */

#ifndef EPILOG_LOG_H
#define EPILOG_LOG_H

#include <stdio.h>
#include <string.h>
#include <stdarg.h>

extern int g_verbose;

/* log_init — scan argv for --verbose / -v and set g_verbose. */
static inline void log_init(int argc, char *argv[])
{
    int i;
    g_verbose = 0;
    for (i = 1; i < argc; ++i) {
        if (strncmp(argv[i], "--verbose", 10) == 0 ||
            strncmp(argv[i], "-v",         3) == 0) {
            g_verbose = 1;
        }
    }
}

/* vlog — emit one log line if verbose is on. */
static inline void vlog(const char *subsys, const char *fmt, ...)
{
    va_list ap;
    if (!g_verbose) { return; }
    fprintf(stderr, "[%s] ", subsys);
    va_start(ap, fmt);
    vfprintf(stderr, fmt, ap);
    va_end(ap);
    fputc('\n', stderr);
}

#define LOG_INIT(argc, argv)          log_init((argc), (argv))
#define VLOG(fmt, ...)                vlog("epilog", (fmt), __VA_ARGS__)
#define VLOG_SUBSYS(s, fmt, ...)      vlog((s),      (fmt), __VA_ARGS__)

#endif /* EPILOG_LOG_H */

