1	/*
2	 * main.c — Entry point for the Epilog logic programming runtime.
3	 *
4	 * Usage:
5	 *   epilog [--verbose|-v] [file.pl ...]
6	 *
7	 * JPL rules: no recursion, bounded loops, no post-init malloc.
8	 */
9	
10	#include "include/repl.h"
11	#include "include/log.h"
12	#include <stdio.h>
13	#include <string.h>
14	
15	int g_verbose = 0;  /* definition; declared extern in log.h */
16	
17	int main(int argc, char *argv[])
18	{
19	    static ReplState s;  /* too large for the stack (~8 MB) */
20	    int              i;
21	
22	    LOG_INIT(argc, argv);
23	
24	    if (repl_init(&s) < 0) {
25	        fprintf(stderr, "epilog: failed to initialise runtime\n");
26	        return 1;
27	    }
28	
29	    VLOG("%s", "runtime initialised");
30	
31	    /* load any .pl files passed as arguments (skip flags) */
32	    for (i = 1; i < argc; ++i) {
33	        if (strncmp(argv[i], "--verbose", 10) == 0) { continue; }
34	        if (strncmp(argv[i], "-v",         3) == 0) { continue; }
35	        if (argv[i][0] == '-') { continue; }
36	        VLOG("loading file: %s", argv[i]);
37	        if (repl_load_file(&s, argv[i]) < 0) { return 1; }
38	    }
39	
40	    repl_run(&s);
41	    return 0;
42	}
